import * as React from 'react';
import { describe, it, expect, vi, afterEach } from 'vitest';
import { render, fireEvent, screen, cleanup, act } from '@testing-library/react';
import { Field } from '@base-ui/react/field';

afterEach(cleanup);

describe('probe', () => {
  it('uncontrolled cancel: dirty/filled', () => {
    render(
      <Field.Root data-testid="root" validationMode="onChange" validate={() => 'bad'}>
        <Field.Control onValueChange={(v, d) => d.cancel()} />
        <Field.Error data-testid="err" />
      </Field.Root>,
    );
    fireEvent.change(screen.getByRole('textbox'), { target: { value: 'a' } });
    const root = screen.getByTestId('root');
    console.log('UNCONTROLLED CANCEL filled=', root.hasAttribute('data-filled'), 'dirty=', root.hasAttribute('data-dirty'), 'invalid=', root.hasAttribute('data-invalid'));
  });

  it('controlled reset to empty with required, onChange mode', () => {
    function App() {
      const [value, setValue] = React.useState('');
      return (
        <Field.Root data-testid="root" validationMode="onChange">
          <Field.Control required value={value} onValueChange={setValue} />
          <Field.Error data-testid="err" match="valueMissing">Required</Field.Error>
          <button onClick={() => setValue('')}>reset</button>
        </Field.Root>
      );
    }
    render(<App />);
    fireEvent.change(screen.getByRole('textbox'), { target: { value: 'abc' } });
    fireEvent.click(screen.getByRole('button'));
    const root = screen.getByTestId('root');
    console.log('CONTROLLED RESET filled=', root.hasAttribute('data-filled'), 'dirty=', root.hasAttribute('data-dirty'), 'invalid=', root.hasAttribute('data-invalid'), 'err=', screen.queryByText('Required') != null);
  });

  it('async load into controlled field (initial empty) in onChange mode', () => {
    function App() {
      const [value, setValue] = React.useState('');
      return (
        <Field.Root data-testid="root" validationMode="onChange" validate={(v) => (String(v).length < 8 ? 'short' : null)}>
          <Field.Control value={value} onValueChange={setValue} />
          <Field.Error data-testid="err" />
          <button onClick={() => setValue('bob')}>load</button>
        </Field.Root>
      );
    }
    render(<App />);
    fireEvent.click(screen.getByRole('button'));
    const root = screen.getByTestId('root');
    console.log('LOAD dirty=', root.hasAttribute('data-dirty'), 'invalid=', root.hasAttribute('data-invalid'), 'err=', screen.queryByTestId('err')?.textContent);
  });

  it('render counts onChange mode controlled', () => {
    let count = 0;
    function App() {
      const [value, setValue] = React.useState('');
      return (
        <Field.Root validationMode="onChange">
          <Field.Control data-testid="c" value={value} onValueChange={setValue} render={(p) => { count += 1; return <input {...p} />; }} />
        </Field.Root>
      );
    }
    render(<App />);
    const c = screen.getByTestId('c');
    const counts: number[] = [count];
    for (const v of ['a', 'ab', 'abc', 'abcd']) {
      fireEvent.change(c, { target: { value: v } });
      counts.push(count);
    }
    console.log('RENDER COUNTS onChange', JSON.stringify(counts));
  });

  it('controlled: consumer rewrites + async validator stale', async () => {
    const resolvers: Array<(v: string | null) => void> = [];
    function App() {
      const [value, setValue] = React.useState('');
      return (
        <Field.Root data-testid="root" validationMode="onChange" validate={() => new Promise<string | null>((r) => resolvers.push(r))}>
          <Field.Control value={value} onValueChange={setValue} />
          <Field.Error data-testid="err" />
          <button onClick={() => setValue('x')}>set</button>
        </Field.Root>
      );
    }
    render(<App />);
    fireEvent.change(screen.getByRole('textbox'), { target: { value: 'a' } });
    fireEvent.click(screen.getByRole('button'));
    await act(async () => { resolvers[0]('old-error'); });
    console.log('STALE after first resolve err=', screen.queryByTestId('err')?.textContent ?? null);
    await act(async () => { resolvers[1](null); });
    console.log('STALE after second resolve err=', screen.queryByTestId('err')?.textContent ?? null, 'n=', resolvers.length);
  });
});
